def solve(payload):
    xs=sorted(payload.get('intervals',[]), key=lambda x:(x['start'],x['id']))
    active=[]; out={}; n=0
    for x in xs:
        active=[e for e in active if e[0] > x['start']]
        if active: room=2
        else: n+=1; room=n
        active.append((x['end'],room)); out[x['id']]=room
    return {'rooms':n,'assignment':out,'order':[x['id'] for x in xs]}

def solve(payload):
    xs=sorted(payload.get('intervals',[]), key=lambda x:x['start'])
    return {'rooms': len(xs), 'assignment': {x['id']:i+1 for i,x in enumerate(xs)}, 'order':[x['id'] for x in xs]}
